mapper.select:
SELECT *
FROM lunaerp_finance_invoice_application
WHERE id = #{id}
  AND deleted = 1
  AND status = 'DRAFT'
  AND tenant_id = #{tenantId}

mapper.update:
UPDATE lunaerp_finance_invoice_application
SET deleted = 0,
    status = 'DRAFT',
    updater = #{updater},
    update_time = #{now}
WHERE id = #{id}
  AND deleted = 1
  AND status = 'DRAFT'
  AND tenant_id = #{tenantId}

mapper.delete:
DELETE FROM lunaerp_finance_invoice_application
WHERE id = #{id}
  AND deleted = 1
  AND status = 'DRAFT'
  AND tenant_id = #{tenantId}
